    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count 1s and 2s
    count_1 = a.count(1)
    count_2 = a.count(2)

    # If we have at least one 2, start with 2
    if count_2 > 0:
        result = [2]
        count_2 -= 1

        # Alternate between 1 and 2
        for i in range(n - 1):
            if count_2 > 0:
                result.append(2)
                count_2 -= 1
            else:
                result.append(1)
    else:
        # All are 1s, just output them
        result = a

    print(' '.join(map(str, result)))

if __name__ == "__main__":
