def solve():
    a, b, c = map(int, sys.stdin.readline().split())

    # Check if a solution is possible
    if (c - a + b) % 2 != 0:
        print("Impossible")
        return

    y = (c - a + b) // 2
    x = (a + b - c) // 2
    z = (a + c - b) // 2

    if x >= 0 and y >= 0 and z >= 0:
        print(f"{x} {y} {z}")
    else:
        print("Impossible")

if __name__ == "__main__":
    solve()
