def solve():
    n, m, k = map(int, input().split())

    # Compute Grundy numbers for all lengths from k to m
    g = [0] * (m + 1)

    for L in range(k, m + 1):
        reachable = set()
        # Try all possible splits
        for t in range(2, L + 1):
            if L % t == 0:
                part_length = L // t
                if part_length >= k:
                    # Split into t parts of length part_length
                    # Grundy number = g(part_length) * t
                    reachable.add(g[part_length] * t)

        # Find mex
        mex = 0
        while mex in reachable:
            mex += 1
        g[L] = mex

    # Compute total Grundy number
    total = 0
    for _ in range(n):
        total ^= g[m]

    if total != 0:
        print("Timur")
    else:
        print("Marsel")

solve()
