def solve():
    t = int(input())
    for _ in range(t):
        m = int(input())
        row1 = list(map(int, input().split()))
        row2 = list(map(int, input().split()))

        # Try all m possible paths for Alice
        min_bob_score = float('inf')

        # For each possible path, Alice can make her down move at position k (1-indexed)
        for k in range(1, m + 1):
            # Mark cells visited by Alice
            visited = [[False] * m for _ in range(2)]

            # Alice's path: down at position k
            # She goes right (k-1) times, then down, then right (m-k) times
            for j in range(k - 1):
                visited[1][j] = True
            visited[1][k - 1] = True
            for j in range(k, m):
                visited[1][j] = True

            # Now find Bob's optimal path
            # dp[i][j] = maximum score Bob can get from (1, 1) to (i, j)
            dp = [[0] * m for _ in range(2)]

            # Initialize dp[1][0]
            if not visited[1][0]:
                dp[1][0] = row1[0]
            else:
                dp[1][0] = 0

            # Fill dp for row 1
            for j in range(1, m):
                if not visited[1][j]:
                    dp[1][j] = dp[1][j - 1] + row1[j]
                else:
                    dp[1][j] = 0

            # Fill dp for row 2
            for j in range(1, m):
                if not visited[2][j]:
                    dp[2][j] = max(dp[1][j], dp[2][j - 1]) + row2[j]
                else:
                    dp[2][j] = 0

            # Bob's maximum score is dp[2][m - 1]
            min_bob_score = min(min_bob_score, dp[2][m - 1])

        print(min_bob_score)

