a = list(map(int, input().split()))

# Check if it's possible
# If we have an odd number of 1s, it's impossible
if sum(a) % 2 != 0:
    print("NO")
else:
    print("YES")
    operations = []

    # Greedy approach: iterate from left to right
    for i in range(n - 2):
        if a[i] == 1:
            # Flip positions i, i+1, i+2
            a[i] ^= 1
            a[i+1] ^= 1
            a[i+2] ^= 1
            operations.append((i+1, i+2, i+3))  # 1-indexed

    # Check if all are zeros
    if all(x == 0 for x in a):
        print(len(operations))
        for op in operations:
            print(op[0], op[1], op[2])
    else:
        print("NO")
"}

