def solve():
    N, M = map(int, input().split())
    edges = [[] for _ in range(N + 1)]
    for _ in range(M):
        A, B = map(int, input().split())
        edges[A].append(B)

    # For each vertex, trace its path
    for start in range(1, N + 1):
        visited = set()
        path = []
        current = start

        while True:
            if current in visited:
                # Found a cycle
                cycle = []
                for v in path:
                    if v == current:
                        cycle.append(v)
                        break
                cycle.reverse()

                # Check if all vertices in the cycle have exactly one incoming and one outgoing edge within the cycle
                in_deg = {v: 0 for v in cycle}
                out_deg = {v: 0 for v in cycle}

                for v in cycle:
                    for neighbor in edges[v]:
                        if neighbor in cycle:
                            out_deg[v] += 1

                for v in cycle:
                    for neighbor in edges:
                        if neighbor == v:
                            for u in edges[neighbor]:
                                if u in cycle:
                                    in_deg[v] += 1

                if all(in_deg[v] == 1 and out_deg[v] == 1 for v in cycle):
                    print(len(cycle))
                    for v in cycle:
                        print(v)
                    return

                break

            visited.add(current)
            path.append(current)
            current = edges[current][0] if edges[current] else None

        if current is None:
            break

    print(-1)

solve()
