def cross_product(a, b):
    """Calculate the cross product of two 2D vectors"""
    return a[0] * b[1] - a[1] * b[0]

def dot_product(a, b):
    """Calculate the dot product of two 2D vectors"""
    return a[0] * b[0] + a[1] * b[1]

def vector_length_squared(a):
    """Calculate the squared length of a 2D vector"""
    return a[0] * a[0] + a[1] * a[1]

def is_point_on_segment(p, s):
    """Check if point p lies on segment s"""
    # Check if p is collinear with s
    if cross_product((s[1][0] - s[0][0]), (s[1][1] - s[0][1]), (p[0] - s[0][0]), (p[1] - s[0][1])) != 0:
        return False

    # Check if p is between the endpoints of s
    return (min(s[0][0], s[1][0]) <= p[0] <= max(s[0][0], s[1][0]) and
            min(s[0][1], s[1][1]) <= p[1] <= max(s[0][1], s[1][1]))

def segment_intersection(s1, s2):
    """Find the intersection point of two segments s1 and s2"""
    # s1 = (A, B), s2 = (C, D)
    A, B = s1
    C, D = s2

    # Vectors
    AB = (B[0] - A[0], B[1] - A[1])
    AC = (C[0] - A[0], C[1] - A[1])
    AD = (D[0] - A[0], D[1] - A[1])
    CD = (D[0] - C[0], D[1] - C[1])

    # Check if segments intersect
    if cross_product(AB, AC) * cross_product(AB, AD) > 0:
        return None  # Segments don't intersect

    # Find intersection point
    t = cross_product(AC, CD) / cross_product(AB, CD)
    u = cross_product(AC, AB) / cross_product(AD, AB)

    if t < 0 or t > 1 or u < 0 or u > 1:
        return None  # Intersection outside segments

    return (A[0] + t * AB[0], A[1] + t * AB[1])

def angle_between_segments(s1, s2):
    """Check if the angle between segments s1 and s2 is > 0 and ≤ 90 degrees"""
    A, B = s1
    C, D = s2

    # Vectors from common endpoint
    if A == C:
        v1 = (B[0] - A[0], B[1] - A[1])
        v2 = (D[0] - A[0], D[1] - A[1])
    elif A == D:
        v1 = (B[0] - A[0], B[1] - A[1])
        v2 = (C[0] - A[0], C[1] - A[1])
    elif B == C:
        v1 = (A[0] - B[0], A[1] - B[1])
        v2 = (D[0] - B[0], D[1] - B[1])
    elif B == D:
        v1 = (A[0] - B[0], A[1] - B[1])
        v2 = (C[0] - B[0], C[1] - B[1])
    else:
        return False  # No common endpoint

    # Check if angle is > 0 and ≤ 90 degrees
    # Angle > 0 means vectors are not collinear
    if cross_product(v1, v2) == 0:
        return False

    # Angle ≤ 90 degrees means dot product > 0
    if dot_product(v1, v2) <= 0:
        return False

    return True

def proportion_condition(segment, intersection):
    """Check if intersection divides segment in proportion ≥ 1/4"""
    A, B = segment
    P = intersection

    # Lengths of the two parts
    len1 = vector_length_squared((P[0] - A[0], P[1] - A[1]))
    len2 = vector_length_squared((B[0] - P[0], B[1] - P[1]))

    # Find which part is shorter
    if len1 <= len2:
        return len1 >= (len2 / 4)
    else:
        return len2 >= (len1 / 4)

def solve():
    t = int(input())

    for _ in range(t):
        segments = []
        for _ in range(3):
            x1, y1, x2, y2 = map(int, input().split())
            segments.append(((x1, y1), (x2, y2)))

        found = False

        # Try all permutations of which segment is first, second, third
        for first_idx in range(3):
            for second_idx in range(3):
                if first_idx == second_idx:
                    continue
                third_idx = 3 - first_idx - second_idx

                first = segments[first_idx]
                second = segments[second_idx]
                third = segments[third_idx]

                # Check if first and second share a common endpoint
                if not angle_between_segments(first, second):
                    continue

                # Find intersection points
                p1 = segment_intersection(first, third)
                p2 = segment_intersection(second, third)

                if p1 is None or p2 is None:
                    continue

                # Check if intersections are on the segments
                if not is_point_on_segment(p1, first) or not is_point_on_segment(p2, second):
                    continue

                # Check proportion conditions
                if proportion_condition(first, p1) and proportion_condition(second, p2):
                    found = True
                    break
            if found:
                break

        print("YES" if found else "NO")

