def max_overlap(s, t):
    """Return the maximum overlap between string s and string t."""
    max_k = 0
    for k in range(min(len(s), len(t)), -1, -1):
        if s.endswith(t[:k]):
            return k
    return 0

def solve():
    while True:
        n = int(input())
        if n == 0:
            break

        cities = []
        for _ in range(n):
            cities.append(input().strip())

        # DP: dp[mask][i] = minimum length of superstring ending with city i
        # mask: bitmask of included cities
        # i: index of the last city
        dp = [[float('inf')] * n for _ in range(1 << n)]

        # Initialize: start with each city alone
        for i in range(n):
            dp[1 << i][i] = len(cities[i])

        # Fill DP table
        for mask in range(1 << n):
            for i in range(n):
                if not (mask & (1 << i)):
                    continue

                # Try to add a new city j
                for j in range(n):
                    if mask & (1 << j):
                        continue

                    # Calculate overlap between city i and city j
                    overlap = max_overlap(cities[i], cities[j])

                    # Update DP
                    new_mask = mask | (1 << j)
                    new_len = dp[mask][i] + len(cities[j]) - overlap

                    if new_len < dp[new_mask][j]:
                        dp[new_mask][j] = new_len

        # Find the minimum length for all masks that include all cities
        min_len = min(dp[(1 << n) - 1][i] for i in range(n))
        print(min_len)

solve()
